/**
 * Bundled teaching dataset: chocolate bar reviews from Flavors of Cacao.
 *
 * 2,530 bars with cocoa percent and expert rating (1–4 scale), company location,
 * and bean origin. Covers continuous scatter (cocoa vs rating), categorical
 * comparison (origin / company country), and dense heatmaps of review counts.
 *
 * Sourced via TidyTuesday 2022-01-18 from the Flavors of Cacao chocolate database
 * (http://flavorsofcacao.com/chocolate_database.html). The TidyTuesday project
 * releases its curated tables under CC0 1.0; cite Flavors of Cacao as the primary
 * source when publishing charts. See NOTICE and CHOCOLATE_BARS_CITATION.
 */

/**
 * One row in the teaching table.
 *
 * Declared as a type alias, not an interface, so the rows carry an implicit
 * index signature and can be passed to `<GGPlot data={...}>` in a consumer app.
 */
export type ChocolateBarRow = {
  id: string;
  company: string;
  companyLocation: string;
  beanOrigin: string;
  cocoaPercent: number;
  rating: number;
};

